def count_unique_substrings(s: str) -> int:
    """
    This function counts the number of unique substrings in a given string.

    Args:
        s (str): A non-empty string consisting of lowercase English letters.

    Returns:
        int: The number of unique substrings present in the input string s.
    """
    n = len(s)
    unique_substrings = set()

    # Generate all possible substrings
    for i in range(n):
        for j in range(i, n):
            # Add the substring to the set
            unique_substrings.add(s[i:j+1])

    # Return the number of unique substrings
    return len(unique_substrings)

