def decode_string(s: str) -> str:
    stack = []
    cur_num = 0
    cur_str = ''
    for c in s:
        if c.isdigit():
            cur_num = cur_num * 10 + int(c)
        elif c == '[':
            stack.append(cur_str)
            stack.append(cur_num)
            cur_str = ''
            cur_num = 0
        elif c == ']':
            num = stack.pop()
            prev_str = stack.pop()
            cur_str = prev_str + num * cur_str
        else:
            cur_str += c
    return cur_str

