def sparseMatrixMultiply(A, B):
    """
    :type A: List[List[int]]
    :type B: List[List[int]]
    :rtype: List[List[int]]
    """
    # 将矩阵转换为稀疏矩阵
    sparse_A = {}
    sparse_B = {}

    for i, row in enumerate(A):
        for j, val in enumerate(row):
            if val != 0:
                if i not in sparse_A:
                    sparse_A[i] = {}
                sparse_A[i][j] = val

    for i, row in enumerate(B):
        for j, val in enumerate(row):
            if val != 0:
                if j not in sparse_B:
                    sparse_B[j] = {}
                sparse_B[j][i] = val

    # 初始化结果矩阵
    C = [[0 for _ in range(len(B[0]))] for _ in range(len(A))]

    # 计算矩阵乘积
    for i in sparse_A:
        for j in sparse_B:
            if i in sparse_B[j]:
                val = sparse_A[i][j] * sparse_B[j][i]
                C[i][j] = val

    return C

