def length_of_longest_substring(word: str) -> int:
    if not word:
        return 0
    left = 0
    right = 0
    max_length = 0
    char_set = set()
    while right < len(word):
        if word[right] not in char_set:
            char_set.add(word[right])
            max_length = max(max_length, right - left + 1)
            right += 1
        else:
            char_set.remove(word[left])
            left += 1
    return max_length

