def min_sessions(tasks, session_time):
    tasks.sort()
    total = sum(tasks)
    if total <= session_time:
        return 1
    left, right = 1, len(tasks)
    while left <= right:
        mid = (left + right) // 2
        if sum(tasks[:mid]) <= session_time:
            left = mid + 1
        else:
            right = mid - 1
    return left

